import{_ as o}from"./chunks/console-tenants.DGEJUwWF.js";import{_ as a,o as t,c as n,a3 as s}from"./chunks/framework.DhF4LrUq.js";const r="/shipperdog/snapshot/screenshots/roles/console-org-audit-streams.png",f=JSON.parse('{"title":"Organization Admin quickstart","description":"Quickstart for Organization Admins — members and roles, tenants, SSO and SCIM, channel credentials, release governance, and the SIEM audit stream.","frontmatter":{"description":"Quickstart for Organization Admins — members and roles, tenants, SSO and SCIM, channel credentials, release governance, and the SIEM audit stream."},"headers":[],"relativePath":"roles/org-admin.md","filePath":"roles/org-admin.md"}'),i={name:"roles/org-admin.md"};function l(h,e,d,p,g,c){return t(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="organization-admin-quickstart" tabindex="-1">Organization Admin quickstart <a class="header-anchor" href="#organization-admin-quickstart" aria-label="Permalink to &quot;Organization Admin quickstart&quot;">​</a></h1><h2 id="who-you-are" tabindex="-1">Who you are <a class="header-anchor" href="#who-you-are" aria-label="Permalink to &quot;Who you are&quot;">​</a></h2><p>You run your organization on ShipperDog: the members and their roles, the tenants, how people sign in, and the policies that govern every release the organization ships. Your system role is <strong><code>ORG_ADMIN</code></strong>, granted on your organization membership. You are the top of the organization&#39;s own hierarchy — everything inside it is yours to configure, everything outside it (other organizations, the instance itself) is not your surface. If you also personally own applications or run releases, use separate accounts or separate sessions for those tracks — see the <a href="/shipperdog/snapshot/roles/app-owner">App Owner</a> and <a href="/shipperdog/snapshot/roles/release-manager">Release Manager</a> guides.</p><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><p>The widest role in the catalog. In plain language:</p><ul><li><strong>People</strong> — invite members, assign and change their roles, remove them. A role change that removes permissions takes effect on the member&#39;s very next request; removals end their sessions immediately.</li><li><strong>Tenants</strong> — create tenants, manage their settings, and (through the owning-organization overlay) administer members, testers, and devices inside every tenant your organization owns.</li><li><strong>Identity</strong> — configure single sign-on (OIDC and SAML) and SCIM provisioning for the organization.</li><li><strong>Release governance</strong> — define approval workflows, quality-gate definitions, release rings, declarative release policies, and ABAC attribute policies. You also hold the two audited exceptions: overriding a blocking gate and acknowledging a policy hold.</li><li><strong>Distribution and notifications</strong> — manage distribution channels and their store credentials, and decide who hears about which events.</li><li><strong>The SIEM audit stream</strong> — yours alone: configuring the export of the audit trail to your SIEM is deliberately restricted to Organization Admins; no other role holds it.</li><li><strong>Oversight</strong> — read applications, versions, and releases; triage feedback; run analytics recompute; see both dashboards.</li></ul><p>A last-administrator guard protects you: your organization always keeps at least one <code>ORG_ADMIN</code>, so the role can never be accidentally orphaned.</p><h2 id="first-15-minutes" tabindex="-1">First 15 minutes <a class="header-anchor" href="#first-15-minutes" aria-label="Permalink to &quot;First 15 minutes&quot;">​</a></h2><p>The screenshots come from the locally running development stack with its seeded demo world — what you see here is what you will see there.</p><ol><li><p><strong>Sign in and read the dashboard.</strong> The pending-actions panel is personalized to your role: approval steps waiting on administrators, the security-review queue, and failed gates you have authority to override. It deep-links straight to the release each item acts on.</p></li><li><p><strong>Create a tenant.</strong> Open <strong>Tenants</strong> and add the customer or business entity your releases will target. Each tenant starts with its own default tester groups. Lifecycle changes (deactivation and reactivation) live here too — deactivation is reversible and blocks new memberships while preserving all data.</p><p><img src="'+o+'" alt="The tenants listing"></p></li><li><p><strong>Invite your people.</strong> Organization invitations carry the role you want the member to hold — invite an <a href="/shipperdog/snapshot/roles/app-owner">App Owner</a>, a <a href="/shipperdog/snapshot/roles/release-manager">Release Manager</a>, a <a href="/shipperdog/snapshot/roles/qa-engineer">QA Engineer</a>, a <a href="/shipperdog/snapshot/roles/developer">Developer</a>, and your <a href="/shipperdog/snapshot/roles/security-reviewer">reviewers</a>. A fresh member without a functional role can do nothing until you grant one — deny by default, by design. (Member management is an API operation today; the Console surface lands with the console how-tos.)</p></li><li><p><strong>Set up how the organization signs in.</strong> SSO via OIDC or SAML, and SCIM provisioning so joins and leaves follow your identity provider — guides land in <a href="/shipperdog/snapshot/how-to/console/sso-oidc-saml">SSO</a> and <a href="/shipperdog/snapshot/how-to/console/scim-provisioning">SCIM provisioning</a>.</p></li><li><p><strong>Route the audit trail to your SIEM.</strong> The audit stream export is the one surface only you hold. Open <strong>Audit Streams</strong> and point it at your HTTPS collector or bucket — the immutable trail of every privileged action, shipped off-platform under your own secret references.</p><p><img src="'+r+'" alt="The SIEM audit streams page"></p></li></ol><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><p>Hand-off task list:</p><ul><li>[ ] Read <a href="/shipperdog/snapshot/concepts/tenancy-isolation">tenancy and isolation</a> before creating your first tenants</li><li>[ ] Read <a href="/shipperdog/snapshot/concepts/approvals-gates">approvals and gates</a> and <a href="/shipperdog/snapshot/concepts/rings-and-rollout">rings and rollout</a>, then define your organization&#39;s workflows, gates, and rings</li><li>[ ] Read <a href="/shipperdog/snapshot/concepts/identity-sso">identity and SSO</a> for the authentication models you are configuring</li><li>[ ] Decide your ABAC posture: <a href="/shipperdog/snapshot/concepts/authorization">authorization</a></li><li>[ ] How-tos as they land: <a href="/shipperdog/snapshot/how-to/console/tenants">tenants</a>, <a href="/shipperdog/snapshot/how-to/console/sso-oidc-saml">SSO</a>, <a href="/shipperdog/snapshot/how-to/console/scim-provisioning">SCIM</a>, <a href="/shipperdog/snapshot/how-to/console/siem-streams">SIEM streams</a>, <a href="/shipperdog/snapshot/how-to/console/abac-policies">ABAC policies</a>, <a href="/shipperdog/snapshot/how-to/console/audit-log">audit log</a></li><li>[ ] Onboard testers with the QA Engineer&#39;s <a href="/shipperdog/snapshot/roles/qa-engineer">tester-invitation flow</a></li></ul>',13)])])}const y=a(i,[["render",l]]);export{f as __pageData,y as default};
